<?php
declare(strict_types=1);
function extension_action(string $action,array $b,array $u):?array {
 if($action==='hazard-report'){
  permit($u,'driver');if(empty($b['stopped']))fail(422,'Stop safely before reporting.');$p=validate_place($b['location']??[]);$kind=required($b,'kind',32);if(!in_array($kind,['road_closed','collision','flooding','obstruction','map_error']))fail(422,'Choose a road report type.');$id=identifier();sql('INSERT INTO rs_cases(id,user_id,category,subject,due_at) VALUES(?,?,"map",?,DATE_ADD(UTC_TIMESTAMP(),INTERVAL 1 DAY))',[$id,$u['id'],'Road report: '.$kind]);sql('INSERT INTO rs_case_messages(case_id,actor_id,body) VALUES(?,?,?)',[$id,$u['id'],j(['type'=>$kind,'confirmed_location'=>$p,'stopped_confirmation'=>true,'details'=>text_value($b['message']??'',1000)])]);audit($u['id'],'hazard.report',$id,'Driver confirmed type and location while stopped');return ['ok'=>true,'case_id'=>$id];
 }
 if(in_array($action,['lost-item','lost-item-update'])){
  $trip=trip_row(required($action==='lost-item'?$_GET:$b,'trip_id',32),$action==='lost-item-update');participant($u,$trip);if(!in_array($trip['status'],TERMINAL_TRIPS)||!$trip['driver_id'])fail(409,'Use this workflow for your ended, assigned trip.');$item=row('SELECT * FROM rs_lost_items WHERE trip_id=?'.($action==='lost-item-update'?' FOR UPDATE':''),[$trip['id']]);if($action==='lost-item')return ['item'=>$item,'policy'=>'Support coordinates the handoff. Personal phone numbers and home addresses are not shared. Both parties must consent and confirm return. No return fee is configured.'];
  $ownCustomer=$u['id']===(int)$trip['customer_id'];$next=required($b,'next',24);
  if(!$item){if($next!=='report')fail(409,'Report the item first.');$description=required($b,'description',1000);$id=identifier();sql('INSERT INTO rs_cases(id,user_id,trip_id,category,subject,due_at) VALUES(?,?,?,"lost_item","Lost-item coordination",DATE_ADD(UTC_TIMESTAMP(),INTERVAL 1 DAY))',[$id,$u['id'],$trip['id']]);sql('INSERT INTO rs_case_messages(case_id,actor_id,body) VALUES(?,?,?)',[$id,$u['id'],$description]);sql('INSERT INTO rs_lost_items(trip_id,case_id,description) VALUES(?,?,?)',[$trip['id'],$id,$description]);}
  else{version_guard($item,$b);if($next==='consent'){sql('UPDATE rs_lost_items SET '.($ownCustomer?'customer_consent':'driver_consent').'=?,version=version+1,updated_at=UTC_TIMESTAMP() WHERE trip_id=?',[!empty($b['consent']),$trip['id']]);}
   elseif($next==='found'){if($item['status']!=='reported')fail(409,'The item report changed.');if($ownCustomer)fail(403,'Only the assigned driver confirms that they found the item.');sql('UPDATE rs_lost_items SET status="found",version=version+1,updated_at=UTC_TIMESTAMP() WHERE trip_id=?',[$trip['id']]);}
   elseif($next==='handoff'){if(!in_array($item['status'],['found','handoff_pending'])||$item[$ownCustomer?'customer_received':'driver_handoff'])fail(409,'This handoff action was already recorded or the item is not ready.');if(!$item['customer_consent']||!$item['driver_consent'])fail(409,'Both parties must consent to support coordination first.');sql('UPDATE rs_lost_items SET '.($ownCustomer?'customer_received':'driver_handoff').'=1,status=IF('.($ownCustomer?'driver_handoff':'customer_received').'=1,"returned","handoff_pending"),version=version+1,updated_at=UTC_TIMESTAMP() WHERE trip_id=?',[$trip['id']]);}
   else fail(422,'Choose a valid item action.');}
  audit($u['id'],'lost_item.'.$next,$trip['id'],'Participant action; private contact remains undisclosed');$to=$ownCustomer?$trip['driver_id']:$trip['customer_id'];notify((int)$to,'support','Lost-item status updated','Open your ended trip for consent and handoff status.',$trip['id']);return ['ok'=>true];
 }
 if($action==='catalog'){ $result= ['content'=>public_content($u['locale']),'promotions'=>rows('SELECT p.code,p.description,p.discount_minor,p.expires_at FROM rs_promos p WHERE active=1 AND expires_at>UTC_TIMESTAMP() AND NOT EXISTS(SELECT 1 FROM rs_redemptions r WHERE r.promo_id=p.id AND r.user_id=?) AND (SELECT COUNT(*) FROM rs_redemptions r WHERE r.promo_id=p.id)<p.maximum_uses',[$u['id']])];if(!feature_enabled($u,'promotions'))$result['promotions']=[];return $result;}

 if($action==='intake-update'){$i=row('SELECT * FROM rs_intakes WHERE id=? FOR UPDATE',[required($b,'id',32)])??fail(404,'Intake not found.');permit($u,$i['kind']==='recovery'?'access':'safety');version_guard($i,$b);$next=required($b,'status',24);if(!in_array($next,['pending','in_review','verified','rejected','completed']))fail(422,'Choose a review status.');$reason=required($b,'reason',1000);if($next==='verified'&&strlen($reason)<20)fail(422,'Record the independently checked identity evidence and verification method.');sql('UPDATE rs_intakes SET status=?,public_reply=?,owner_id=?,version=version+1,updated_at=UTC_TIMESTAMP() WHERE id=?',[$next,required($b,'reply',2000),$u['id'],$i['id']]);audit($u['id'],'intake.'.$next,$i['id'],$reason);return ['ok'=>true];}
 if($action==='trip-change-quote'){
  permit($u,'customer');$t=trip_row(required($b,'trip_id',32),true);if((int)$t['customer_id']!==$u['id'])fail(403,'Change your own trip.');version_guard($t,$b);if(!in_array($t['status'],['assigned','driver_arriving','arrived','in_progress']))fail(409,'Route changes require an assigned, unfinished trip.');$s=decode($t['snapshot']);$destination=validate_place($b['destination']??[]);$stops=array_map('validate_place',$b['stops']??[]);$visited=(int)(row('SELECT completed_stops FROM rs_trip_progress WHERE trip_id=?',[$t['id']])['completed_stops']??0);for($i=0;$i<$visited;$i++)if(!isset($stops[$i])||distance_m((float)$stops[$i]['lat'],(float)$stops[$i]['lng'],(float)$s['stops'][$i]['lat'],(float)$s['stops'][$i]['lng'])>10)fail(409,'Keep the completed stops unchanged and in order when updating the remaining itinerary.');if(count($stops)>(int)config('operations')['max_stops'])fail(422,'Too many stops.');$path=array_merge([$s['pickup']],$stops,[$destination]);$routing=road_route($path,$s['product']['key']);$m=$routing['distance_m'];$base=(int)(round($m*(int)$s['rate_minor']/100000)*100);$s['destination']=$destination;$s['stops']=$stops;$s['route']=$routing['route'];$s['route_source']=$routing['source'];$s['route_duration_seconds']=$routing['duration_seconds'];$s['distance_m']=$m;$s['base_fare_minor']=$base;$s['discount_minor']=min($base,(int)$s['discount_minor']);$s['fare_minor']=$base-$s['discount_minor'];$id=identifier();sql('INSERT INTO rs_trip_changes(id,trip_id,customer_id,trip_version,before_json,after_json,fare_minor,expires_at) VALUES(?,?,?,?,?,?,?,DATE_ADD(UTC_TIMESTAMP(),INTERVAL 2 MINUTE))',[$id,$t['id'],$u['id'],$t['version'],$t['snapshot'],j($s),$s['fare_minor']]);return ['change'=>['id'=>$id,'fare_minor'=>$s['fare_minor'],'previous_fare_minor'=>(int)$t['fare_minor'],'snapshot'=>$s,'policy'=>'Full itinerary repriced from original pickup at the accepted rate. It applies only after customer confirmation and driver acceptance.']];
 }
 if($action==='trip-change-confirm'){
  permit($u,'customer');$c=row('SELECT * FROM rs_trip_changes WHERE id=? FOR UPDATE',[required($b,'id',32)])??fail(404,'Change quote not found.');$t=trip_row($c['trip_id'],true);if((int)$c['customer_id']!==$u['id'])fail(403,'Confirm your own route change.');if($c['status']!=='quoted'||strtotime($c['expires_at'])<time()||(int)$c['trip_version']!==(int)$t['version'])fail(409,'This route-change quote expired or the trip changed.');sql('UPDATE rs_trip_changes SET status="superseded" WHERE trip_id=? AND status="pending"',[$t['id']]);sql('UPDATE rs_trip_changes SET status="pending" WHERE id=?',[$c['id']]);event($t,$u,'route_change_requested',['change_id'=>$c['id'],'fare_minor'=>$c['fare_minor']]);notify((int)$t['driver_id'],'trip','Route change requested','Review the requested stops, destination and fare before accepting.',$t['id']);return ['ok'=>true];
 }
 if($action==='trip-change-decision'){
  permit($u,'driver');$c=row('SELECT * FROM rs_trip_changes WHERE id=? FOR UPDATE',[required($b,'id',32)])??fail(404,'Route change not found.');$t=trip_row($c['trip_id'],true);if((int)$t['driver_id']!==$u['id'])fail(403,'Only the assigned driver responds to this change.');if($c['status']!=='pending'||strtotime($c['expires_at'])<time()||(int)$t['version']!==(int)$c['trip_version']||in_array($t['status'],TERMINAL_TRIPS))fail(409,'This route change expired or the trip changed.');$accept=($b['decision']??'')==='accept';if(!in_array($b['decision']??'',['accept','decline']))fail(422,'Accept or decline the route change.');sql('UPDATE rs_trip_changes SET status=? WHERE id=?',[$accept?'accepted':'declined',$c['id']]);if($accept)sql('UPDATE rs_trips SET snapshot=?,fare_minor=?,version=version+1 WHERE id=?',[$c['after_json'],$c['fare_minor'],$t['id']]);event($t,$u,$accept?'route_change_accepted':'route_change_declined',['change_id'=>$c['id'],'fare_minor'=>$c['fare_minor']]);notify((int)$t['customer_id'],'trip',$accept?'Route change accepted':'Route change declined',$accept?'The confirmed route and price were updated.':'Your original accepted route and price remain in place.',$t['id']);return ['ok'=>true];
 }
 if($action==='no-show'){
  permit($u,'driver');$t=trip_row(required($b,'trip_id',32),true);if((int)$t['driver_id']!==$u['id'])fail(403,'Only the assigned driver records no-show.');version_guard($t,$b);if($t['status']!=='arrived'||strtotime($t['arrived_at'])>time()-300)fail(409,'Wait at least five minutes after confirmed arrival.');$contact=required($b,'contact_attempt',500);sql('UPDATE rs_trips SET status="no_show",ended_at=UTC_TIMESTAMP(),version=version+1 WHERE id=?',[$t['id']]);release_trip($t);event($t,$u,'customer_no_show',['contact_attempt'=>$contact,'fee_minor'=>0]);notify((int)$t['customer_id'],'trip','Pickup ended','The driver recorded no-show after the waiting period. No fee was charged.',$t['id']);return ['ok'=>true];
 }

 return null;
}
